//! The read-only Win32 function inventory (`data/win32-functions.csv`).
//!
//! The file is generated by the `vba-winapi-gen` dev tool from Microsoft's
//! Win32 metadata and is never edited by hand. It lists every function the
//! metadata declares as a DLL export, with the parameter and return types as
//! the metadata states them. It says what *exists*; which functions vba-rs
//! *implements* is the job of [`crate::catalog`].
//!
//! Columns: `dll,symbol,base,charset,pair,params,ret,conv,arch`
//! (see the generator for their exact meaning). Rows are sorted by
//! `(dll, symbol, arch)`.

use std::fmt;
use std::sync::OnceLock;

const CSV: &str = include_str!("../data/win32-functions.csv");

/// Direction of a parameter as the metadata states it.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Direction {
    /// `[in]`.
    In,
    /// `[out]`.
    Out,
    /// `[in, out]`.
    InOut,
    /// The metadata does not say.
    Unspecified,
}

/// One parameter of an inventory entry.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Param {
    /// Parameter name.
    pub name: &'static str,
    /// Direction.
    pub direction: Direction,
    /// Whether the metadata marks the parameter optional.
    pub optional: bool,
    /// Type as rendered by the generator (`u32`, `*mut u32`, `HANDLE`, ...).
    pub ty: &'static str,
}

/// One exported Win32 function.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Entry {
    /// Lower-case library name without extension (`kernel32`).
    pub dll: &'static str,
    /// Exported symbol (`lstrcpyA`).
    pub symbol: &'static str,
    /// Symbol without its `A`/`W` suffix when it belongs to a pair, else the symbol.
    pub base: &'static str,
    /// `Some('A')`/`Some('W')` when the symbol is one half of an A/W pair.
    pub charset: Option<char>,
    /// Whether both an `A` and a `W` variant exist in this DLL.
    pub paired: bool,
    /// Return type as rendered by the generator.
    pub ret: &'static str,
    /// Calling convention: `system` (stdcall), `C` (cdecl) or `-` (unstated).
    pub conv: &'static str,
    /// `all`, or `+` joined `x86`, `x64`, `arm64`.
    pub arch: &'static str,
    params: &'static str,
}

impl Entry {
    /// The parameters, in order.
    pub fn params(&self) -> impl Iterator<Item = Param> + '_ {
        self.params
            .split('|')
            .filter(|p| !p.is_empty())
            .map(parse_param)
    }

    /// Number of parameters.
    pub fn param_count(&self) -> usize {
        self.params().count()
    }

    /// A readable signature, e.g. `Sleep(dwMilliseconds: in u32) -> void`.
    pub fn signature(&self) -> String {
        self.to_string()
    }
}

impl fmt::Display for Entry {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}(", self.symbol)?;
        for (i, p) in self.params().enumerate() {
            if i > 0 {
                f.write_str(", ")?;
            }
            let dir = match p.direction {
                Direction::In => "in ",
                Direction::Out => "out ",
                Direction::InOut => "inout ",
                Direction::Unspecified => "",
            };
            let opt = if p.optional { "optional " } else { "" };
            write!(f, "{}: {opt}{dir}{}", p.name, p.ty)?;
        }
        write!(f, ") -> {}", self.ret)
    }
}

fn parse_param(raw: &'static str) -> Param {
    let mut it = raw.splitn(3, ':');
    let name = it.next().unwrap_or("");
    let dir = it.next().unwrap_or("-");
    let ty = it.next().unwrap_or("");
    let (dir, optional) = match dir.strip_suffix('?') {
        Some(d) => (d, true),
        None => (dir, false),
    };
    Param {
        name,
        direction: match dir {
            "in" => Direction::In,
            "out" => Direction::Out,
            "inout" => Direction::InOut,
            _ => Direction::Unspecified,
        },
        optional,
        ty,
    }
}

fn parse(text: &'static str) -> Result<Vec<Entry>, String> {
    let mut rows = Vec::new();
    for (n, line) in text.lines().enumerate().skip(1) {
        let f: Vec<&'static str> = line.split(',').collect();
        let [dll, symbol, base, charset, pair, params, ret, conv, arch] = f[..] else {
            return Err(format!(
                "line {}: expected 9 fields, found {}",
                n + 1,
                f.len()
            ));
        };
        rows.push(Entry {
            dll,
            symbol,
            base,
            charset: charset.chars().next().filter(|c| *c != '-'),
            paired: pair == "AW",
            ret,
            conv,
            arch,
            params,
        });
    }
    Ok(rows)
}

/// Every inventory entry, sorted by `(dll, symbol, arch)`.
pub fn inventory() -> &'static [Entry] {
    static ROWS: OnceLock<Vec<Entry>> = OnceLock::new();
    ROWS.get_or_init(|| parse(CSV).expect("embedded win32-functions.csv is well formed"))
}

/// All entries exporting `symbol` from `dll` (several only when the
/// metadata distinguishes architectures). Exact, case-sensitive symbol.
pub fn lookup_all(dll: &str, symbol: &str) -> &'static [Entry] {
    let rows = inventory();
    let key = |e: &Entry| (e.dll, e.symbol);
    let start = rows.partition_point(|e| key(e) < (dll, symbol));
    let len = rows[start..]
        .iter()
        .take_while(|e| key(e) == (dll, symbol))
        .count();
    &rows[start..start + len]
}

/// The first entry exporting `symbol` from `dll`.
pub fn lookup(dll: &str, symbol: &str) -> Option<&'static Entry> {
    lookup_all(dll, symbol).first()
}

/// Entries exporting `symbol` from any DLL (linear scan; for diagnostics).
pub fn lookup_any_dll(symbol: &str) -> Vec<&'static Entry> {
    inventory().iter().filter(|e| e.symbol == symbol).collect()
}
